import com.gregtechceu.gtceu.api.sync_system.annotations.SyncToClient;
import com.gregtechceu.gtceu.common.machine.trait.CleanroomReceiverTrait;
import com.gregtechceu.gtceu.utils.GTUtil;
import com.gregtechceu.gtceu.utils.ISubscription;

import it.unimi.dsi.fastutil.ints.Int2IntFunction;
import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.VisibleForTesting;

import java.util.*;

/**
 * A tiered energy machine with recipe logic and item/fluid IO.
 */
public abstract class WorkableTieredMachine extends TieredEnergyMachine implements IRecipeLogicMachine,
                                            IMufflableMachine, IOverclockMachine {

    @Getter
    @SaveField
    @SyncToClient
    public final RecipeLogic recipeLogic;
    @Getter
    public final GTRecipeType[] recipeTypes;
    @Getter
    @Setter
    @SaveField
    public int activeRecipeType;
    @Getter
    protected final CleanroomReceiverTrait cleanroomReceiver;
    @SaveField
    public final NotifiableItemStackHandler importItems, exportItems;
    @SaveField
    public final NotifiableFluidTank importFluids, exportFluids;
    @SaveField
    public final NotifiableComputationContainer importComputation, exportComputation;
    @Getter
    protected final Map<IO, List<RecipeHandlerList>> capabilitiesProxy;
    @Getter
    protected final Map<IO, Map<RecipeCapability<?>, List<IRecipeHandler<?>>>> capabilitiesFlat;
    @SaveField
    @Getter
    protected int overclockTier;
    protected final List<ISubscription> traitSubscriptions;
    @SaveField
    @SyncToClient
    @Getter
    protected boolean isMuffled;
    protected boolean previouslyMuffled = true;

    /**
     * Creates a {@link WorkableTieredMachine}.
     * 
     * @param info                {@link BlockEntityCreationInfo}
     * @param tier                Machine tier.
     * @param recipeLogic         The recipe logic to use.
     * @param importSlots         The amount of item input slots this machine should have (can be 0).
     * @param exportSlots         The amount of item output slots this machine should have (can be 0).
     * @param fluidImportSlots    The amount of fluid input slots this machine should have (can be 0).
     * @param fluidExportSlots    The amount of fluid output slots this machine should have (can be 0).
     * @param energyEmitter       If this machine should input or output energy.
     * @param tankScalingFunction The tank scaling function which determines the capaacity of fluid slots.
     */
    public WorkableTieredMachine(BlockEntityCreationInfo info, int tier,
                                 RecipeLogic recipeLogic, int importSlots,
                                 int exportSlots,
                                 int fluidImportSlots, int fluidExportSlots, boolean energyEmitter,
                                 Int2IntFunction tankScalingFunction) {
        super(info, tier, (energyEmitter ?
                RecipeAmperageEnergyContainer.emitterContainer(GTValues.V[tier] * 64L, GTValues.V[tier], 1) :
                RecipeAmperageEnergyContainer.receiverContainer(GTValues.V[tier] * 64L, GTValues.V[tier], 1)));
        this.overclockTier = getMaxOverclockTier();
        this.recipeTypes = getDefinition().getRecipeTypes();
        this.activeRecipeType = 0;
        this.capabilitiesProxy = new EnumMap<>(IO.class);
        this.capabilitiesFlat = new EnumMap<>(IO.class);
        this.traitSubscriptions = new ArrayList<>();
        this.cleanroomReceiver = attachTrait(new CleanroomReceiverTrait());
        this.recipeLogic = attachTrait(recipeLogic);
        this.recipeLogic.setKeepSubscribing(false);
        this.importItems = attachTrait(new NotifiableItemStackHandler(importSlots, IO.IN));
        this.exportItems = attachTrait(new NotifiableItemStackHandler(exportSlots, IO.OUT));
        this.importFluids = attachTrait(
                new NotifiableFluidTank(fluidImportSlots, tankScalingFunction.applyAsInt(getTier()),
                        IO.IN));
        this.exportFluids = attachTrait(
                new NotifiableFluidTank(fluidExportSlots, tankScalingFunction.applyAsInt(getTier()),
                        IO.OUT));
        this.importComputation = attachTrait(new NotifiableComputationContainer(IO.IN, true));
        this.exportComputation = attachTrait(new NotifiableComputationContainer(IO.OUT, false));
    }

    /**
     * Creates a {@link WorkableTieredMachine} with default settings.<br>
     * The amount of item and fluid input and output slots is determined by the machine's recipe type.
     *
     * @param info                {@link BlockEntityCreationInfo}
     * @param tier                Machine tier.
     * @param energyEmitter       If this machine should input or output energy.
     * @param recipeLogic         The recipe logic to use.
     * @param tankScalingFunction The tank scaling function which determines the capaacity of fluid slots.
     */
    public WorkableTieredMachine(BlockEntityCreationInfo info, int tier, boolean energyEmitter, RecipeLogic recipeLogic,
                                 Int2IntFunction tankScalingFunction) {
        super(info, tier, (energyEmitter ?
                RecipeAmperageEnergyContainer.emitterContainer(GTValues.V[tier] * 64L, GTValues.V[tier], 1) :
                RecipeAmperageEnergyContainer.receiverContainer(GTValues.V[tier] * 64L, GTValues.V[tier], 1)));
        this.overclockTier = getMaxOverclockTier();
        this.recipeTypes = getDefinition().getRecipeTypes();
        this.activeRecipeType = 0;
        this.capabilitiesProxy = new EnumMap<>(IO.class);
        this.capabilitiesFlat = new EnumMap<>(IO.class);
        this.traitSubscriptions = new ArrayList<>();
        this.cleanroomReceiver = attachTrait(new CleanroomReceiverTrait());
        this.recipeLogic = attachTrait(recipeLogic);
        this.recipeLogic.setKeepSubscribing(false);
        this.importItems = attachTrait(
                new NotifiableItemStackHandler(getDefinition().getInputSize(ItemRecipeCapability.CAP, getRecipeTypes()),
                        IO.IN));
        this.exportItems = attachTrait(
                new NotifiableItemStackHandler(
                        getDefinition().getOutputSize(ItemRecipeCapability.CAP, getRecipeTypes()),
                        IO.OUT));
        this.importFluids = attachTrait(
                new NotifiableFluidTank(getDefinition().getInputSize(FluidRecipeCapability.CAP, getRecipeTypes()),
                        tankScalingFunction.applyAsInt(getTier()), IO.IN));
        this.exportFluids = attachTrait(
                new NotifiableFluidTank(getDefinition().getOutputSize(FluidRecipeCapability.CAP, getRecipeTypes()),
                        tankScalingFunction.applyAsInt(getTier()), IO.OUT));
        this.importComputation = attachTrait(new NotifiableComputationContainer(IO.IN, true));
        this.exportComputation = attachTrait(new NotifiableComputationContainer(IO.OUT, false));
    }

    /**
     * Creates a {@link WorkableTieredMachine} with default settings.<br>
     * The amount of item and fluid input and output slots is determined by the machine's recipe type.
     *
     * @param info                {@link BlockEntityCreationInfo}
     * @param tier                Machine tier.
     * @param energyEmitter       If this machine should input or output energy.
     * @param tankScalingFunction The tank scaling function which determines the capaacity of fluid slots.
     */
    public WorkableTieredMachine(BlockEntityCreationInfo info, int tier, boolean energyEmitter,
                                 Int2IntFunction tankScalingFunction) {
        this(info, tier, energyEmitter, new RecipeLogic(), tankScalingFunction);
    }

    //////////////////////////////////////
    // ***** Initialization ******//
    //////////////////////////////////////

    @Override
    public void onLoad() {
        super.onLoad();
        // attach self traits
        Map<IO, List<IRecipeHandler<?>>> ioTraits = new EnumMap<>(IO.class);

        for (var trait : getTraitHolder().getTraitsByInterface(IRecipeHandlerTrait.class)) {
            ioTraits.computeIfAbsent(trait.getHandlerIO(), i -> new ArrayList<>()).add(trait);
        }

        for (var entry : ioTraits.entrySet()) {
            var handlerList = RecipeHandlerList.of(entry.getKey(), entry.getValue());
            this.addHandlerList(handlerList);
            traitSubscriptions.add(handlerList.subscribe(recipeLogic::updateTickSubscription));
        }
    }

    @Override
    public void onUnload() {
        super.onUnload();
        traitSubscriptions.forEach(ISubscription::unsubscribe);
        traitSubscriptions.clear();
        capabilitiesProxy.clear();
        capabilitiesFlat.clear();
    }

    //////////////////////////////////////
    // ********** MISC ***********//
    //////////////////////////////////////

    public void setMuffled(boolean muffled) {
        isMuffled = muffled;
        syncDataHolder.markClientSyncFieldDirty("isMuffled");
    }

    //////////////////////////////////////
    // ******** OVERCLOCK *********//
    //////////////////////////////////////

    @Override
    public int getMaxOverclockTier() {
        return GTUtil.getTierByVoltage(Math.max(energyContainer.getInputVoltage(), energyContainer.getOutputVoltage()));
    }

    @Override
    public int getMinOverclockTier() {
        return 0;
    }

    @Override
    public void setOverclockTier(int tier) {
        if (!isRemote() && tier >= getMinOverclockTier() && tier <= getMaxOverclockTier()) {
            this.overclockTier = tier;
            this.recipeLogic.markLastRecipeDirty();
        }
    }

    @Override
    public long getOverclockVoltage() {
        return Math.min(GTValues.V[getOverclockTier()],
                Math.max(energyContainer.getInputVoltage(), energyContainer.getOutputVoltage()));
    }

    //////////////////////////////////////
    // ****** RECIPE LOGIC *******//
    //////////////////////////////////////

    @Override
    public void clientTick() {
        super.clientTick();
        if (previouslyMuffled != isMuffled) {
            previouslyMuffled = isMuffled;

            recipeLogic.updateSound();
        }
    }

    public GTRecipeType getRecipeType() {
        int index = activeRecipeType >= 0 && activeRecipeType < recipeTypes.length ? activeRecipeType : 0;
        return recipeTypes[index];
    }

    /**
     * Sets a recipe type of the machine.
     * FOR INTERNAL / TESTING USE ONLY!
     * NOT SUPPORTED FOR PRODUCTION USE!
     *
     * @param newType The new recipe type
     */
    @ApiStatus.Internal
    @VisibleForTesting
    public void setRecipeType(GTRecipeType newType) {
        recipeTypes[activeRecipeType] = newType;
    }
}

package com.gregtechceu.gtceu.api.machine.trait;

import com.gregtechceu.gtceu.api.machine.MetaMachine;
import com.gregtechceu.gtceu.api.machine.TickableSubscription;
import com.gregtechceu.gtceu.api.machine.multiblock.MultiblockControllerMachine;
import com.gregtechceu.gtceu.api.machine.trait.notifiable.NotifiableItemStackHandler;
import com.gregtechceu.gtceu.api.sync_system.SyncDataHolder;
import com.gregtechceu.gtceu.api.sync_system.managed.ISyncManaged;
import com.gregtechceu.gtceu.client.model.machine.MachineRenderState;
import com.gregtechceu.gtceu.common.machine.trait.AutoOutputTrait;
import com.gregtechceu.gtceu.common.machine.trait.CleanroomProviderTrait;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;

import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.Nullable;

import java.util.List;
import java.util.function.Predicate;

/**
 * A machine trait represents a generic capability or behaviour that is attached to a machine. <br>
 * <br>
 * For example, machine traits may provide a recipe handler that can handle specific inputs/outputs of a recipe (e.g.
 * {@link NotifiableItemStackHandler} for items). <br>
 * Machine traits can also attach additional behaviours to a machine (e.g. {@link AutoOutputTrait},
 * {@link CleanroomProviderTrait}) <br>
 * <br>
 * If a machine trait implements a capability interface, the trait will be returned by {@link MetaMachine#getCapability}
 * if the machine trait's capability validator prediate is true for that side.
 */
public abstract class MachineTrait implements ISyncManaged {

    @Getter
    protected final SyncDataHolder syncDataHolder = new SyncDataHolder(this);

    private @Nullable MetaMachine machine;
    @Setter
    protected Predicate<@Nullable Direction> capabilityValidator = $ -> true;

    @Getter
    @Setter(onMethod_ = @ApiStatus.Internal)
    private @Nullable String traitName;
    /**
     * The trait's callback priority. Traits with a higher priority will have their events fired
     * first, which may prevent traits with a lower priority from handling some events.
     */
    @Getter
    @Setter
    private int traitPriority = 1;

    public MachineTrait() {}

    public MetaMachine getMachine() {
        if (machine == null) throw new IllegalStateException(
                "Machine trait not attached to machine. Trait initialisation that depends on machine instance should run in onTraitAttached.");
        return machine;
    }

    @Override
    public @Nullable ISyncManaged getParentSyncObject() {
        return getMachine();
    }

    /**
     * A list containing the machine classes which this trait can be attached to.
     * If this trait is being attached to a machine class that does not conform to any of the list elements, an
     * exception is thrown.
     * If this list is empty, the trait can be attached to any machine.
     */
    protected List<Class<?>> validMachineClasses() {
        return List.of();
    }

    @ApiStatus.Internal
    public void setMachine(MetaMachine machine) {
        if (this.machine != null) throw new IllegalStateException("Machine trait already attached to a machine.");
        if (!validMachineClasses().isEmpty() &&
                validMachineClasses().stream().noneMatch(cls -> cls.isAssignableFrom(machine.getClass()))) {
            throw new IllegalArgumentException(
                    "Attempted to attach trait to invalid machine class %s".formatted(machine.getClass()));
        }
        this.machine = machine;
    }

    public @Nullable TickableSubscription subscribeServerTick(@Nullable TickableSubscription last, Runnable runnable) {
        return getMachine().subscribeServerTick(last, runnable);
    }

    public void unsubscribe(@Nullable TickableSubscription current) {
        getMachine().unsubscribe(current);
    }

    public BlockPos getBlockPos() {
        return getMachine().getBlockPos();
    }

    public Level getLevel() {
        return getMachine().getLevel();
    }

    public boolean isRemote() {
        return getMachine().isRemote();
    }

    public final boolean hasCapability(@Nullable Direction side) {
        return capabilityValidator.test(side);
    }

    @Override
    public void markAsChanged() {
        if (machine == null) return;
        getMachine().markAsChanged();
    }

    public MachineRenderState getRenderState() {
        return getMachine().getRenderState();
    }

    public void setRenderState(MachineRenderState state) {
        getMachine().setRenderState(state);
    }

    /**
     * Called when this trait is attached to a machine instance.
     */
    public void onTraitAttached() {}

    /**
     * Called when the machine is loaded. The entire world is not loaded when this method is called.
     * To schedule code to run on the first full world tick, do
     * {@code getMachine().scheduleForNextServerTick(callback)}
     */
    public void onMachineLoad() {}

    /**
     * Called when the machine is about to be unloaded.
     */
    public void onMachineUnload() {}

    /**
     * Called when the machine is destroyed.
     */
    public void onMachineDestroyed() {}

    /**
     * Called when the machine is attached to a controller<br>
     * Only called if this trait is attached to a multiblock part machine.
     *
     * @param controller The multiblock controller
     */
    public void addedToController(MultiblockControllerMachine controller) {}

    /**
     * Called when the machine is removed from a controller<br>
     * Only called if this trait is attached to a multiblock part machine.
     *
     * @param controller The multiblock controller
     */
    public void removedFromController(MultiblockControllerMachine controller) {}

    /**
     * Called when a neighboring block is updated.
     *
     * @param neighborBlock The neighbor block type.
     * @param neighborPos   The neighbor position.
     * @param isMoving      If the neighbor block is moving (e.g. moved by a piston)
     */
    public void onMachineNeighborChanged(Block neighborBlock, BlockPos neighborPos, boolean isMoving) {}
}

package com.gregtechceu.gtceu.api.machine.trait;

import com.gregtechceu.gtceu.GTCEu;
import com.gregtechceu.gtceu.api.machine.MetaMachine;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformer;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformers;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;

import it.unimi.dsi.fastutil.objects.Object2ObjectOpenHashMap;
import it.unimi.dsi.fastutil.objects.ObjectArrayList;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.Unmodifiable;
import org.jetbrains.annotations.UnmodifiableView;

import java.util.*;

public final class MachineTraitHolder {

    private final MetaMachine machine;

    private boolean allowTraitAttachment = true;

    private final List<MachineTrait> traits;

    private final Map<String, MachineTrait> traitsToSave;

    private @Nullable List<MachineTrait> allTraits = null;

    private final Map<Class<?>, List<MachineTrait>> traitsByClass;

    public MachineTraitHolder(MetaMachine machine) {
        this.machine = machine;
        this.traits = new ObjectArrayList<>();
        this.traitsByClass = new Object2ObjectOpenHashMap<>();
        this.traitsToSave = new Object2ObjectOpenHashMap<>();
    }

    /**
     * @return An unmodifiable list of all traits attached to this machine.
     */
    public @Unmodifiable List<MachineTrait> getAllTraits() {
        return allTraits != null ? allTraits : Collections.unmodifiableList(traits);
    }

    /**
     * Gets all traits implementing a specific interface/class
     */
    @SuppressWarnings("unchecked")
    public <T> @Unmodifiable List<T> getTraitsByInterface(Class<T> clazz) {
        if (traitsByClass.containsKey(clazz)) return (List<T>) traitsByClass.get(clazz);

        List<T> list = new ObjectArrayList<>();

        for (var t : getAllTraits()) {
            if (clazz.isAssignableFrom(t.getClass())) list.add(clazz.cast(t));
        }

        if (!allowTraitAttachment) traitsByClass.put(clazz, (List<MachineTrait>) Collections.unmodifiableList(list));
        return list;
    }

    /**
     * Attaches a trait to this machine, with the default trait callback priority of 1.
     * 
     * @param trait The trait to attach
     * @return The attached trait
     */
    public <T extends MachineTrait> T attachTrait(T trait) {
        return attachTrait(trait, 1);
    }

    /**
     * Attaches a trait to this machine. Traits must be attached before {@link MetaMachine#onLoad()}.
     * 
     * @param trait            The trait to attach
     * @param callbackPriority The trait's callback priority. Traits with a higher priority will have their events fired
     *                         first, which may prevent traits with a lower priority from handling some events.
     * @return The attached trait
     */
    public <T extends MachineTrait> T attachTrait(T trait, int callbackPriority) {
        if (!allowTraitAttachment)
            throw new IllegalStateException("Cannot add traits to machine after machine has been loaded.");

        trait.setTraitPriority(callbackPriority);

        addTraitToClassMap(trait.getClass(), trait);
        traits.add(trait);
        traits.sort(Comparator.comparingInt(MachineTrait::getTraitPriority).reversed());

        trait.setMachine(machine);
        trait.onTraitAttached();
        return trait;
    }

    @SuppressWarnings("unchecked")
    private void addTraitToClassMap(Class<? extends MachineTrait> clazz, MachineTrait trait) {
        var list = traitsByClass.computeIfAbsent(clazz, $ -> new ObjectArrayList<>(1));

        list.add(trait);
        list.sort(Comparator.comparingInt(MachineTrait::getTraitPriority).reversed());

        if (!clazz.getSuperclass().equals(MachineTrait.class))
            addTraitToClassMap((Class<? extends MachineTrait>) clazz.getSuperclass(), trait);
    }

    /**
     * Registers a trait with data to be saved or synced to the client.
     * Do not register a persistent trait and also store that trait as a syncable machine field, otherwise the trait
     * data will be duplicated. Use only one sync method.<br>
     * Note: Persistent traits must be attached before data load, or they will not be loaded correctly.
     *
     * @param traitName Unique identifier for this trait.
     * @param trait     The trait to register
     */
    public void attachPersistentTrait(String traitName, MachineTrait trait) {
        attachTrait(trait);
        registerPersistentTrait(traitName, trait);
    }

    /**
     * Registers a trait with data to be saved or synced to the client.
     * Do not register a persistent trait and also store that trait as a syncable machine field, otherwise the trait
     * data will be duplicated. Use only one sync method.<br>
     * Note: Persistent traits must be attached before data load, or they will not be loaded correctly.
     *
     * @param traitName        Unique identifier for this trait.
     * @param callbackPriority The trait's callback priority. Traits with a higher priority will have their events fired
     *                         first, which may prevent traits with a lower priority from handling some events.
     * @param trait            The trait to register
     */
    public void attachPersistentTrait(String traitName, MachineTrait trait, int callbackPriority) {
        attachTrait(trait, callbackPriority);
        registerPersistentTrait(traitName, trait);
    }

    /**
     * Registers a trait with data to be saved or synced to the client.
     * Do not register a persistent trait and also store that trait as a syncable machine field, otherwise the trait
     * data will be duplicated. Use only one sync method.
     *
     * @param traitName Unique identifier for this trait.
     * @param trait     The trait to register
     */
    public MachineTraitHolder registerPersistentTrait(String traitName, MachineTrait trait) {
        if (trait.getMachine() != machine) throw new IllegalArgumentException("Trait does not belong to this machine.");
        if (traitsToSave.containsKey(traitName))
            throw new IllegalArgumentException("Attempted to register duplicate trait save key \"" + traitName + "\"");
        trait.setTraitName(traitName);
        traitsToSave.put(traitName, trait);
        return this;
    }

    /**
     * Gets a trait registered by {@code registerPersistentTrait}
     * 
     * @param traitName the unique identifier for the trait
     * @return the trait, or null if not present
     */
    @SuppressWarnings("unchecked")
    public @Nullable <T extends MachineTrait> T getPersistentTrait(String traitName) {
        MachineTrait trait = traitsToSave.get(traitName);
        return trait == null ? null : (T) trait;
    }

    /**
     * Gets the first trait (trait with highest priority) with the specified class.
     * Also includes traits that are a subtype of the specified class.
     *
     * @param type The trait class to get
     * @return The trait, or null if no traits of the given type are present.
     */
    public <T extends MachineTrait> @Nullable T getTrait(Class<T> type) {
        List<MachineTrait> traitList = traitsByClass.get(type);
        if (traitList == null || traitList.isEmpty()) return null;
        return type.cast(traitList.get(0));
    }

    /**
     * Gets the first trait (trait with highest priority) with the specified class.
     * Also includes traits that are a subtype of the specified class.
     *
     * @param type The trait class to get
     * @return An optional result containing the trait if present.
     */
    public <T extends MachineTrait> Optional<T> getTraitOptional(Class<T> type) {
        return Optional.ofNullable(getTrait(type));
    }

    /**
     * Get all traits with the specified class.
     * Also includes traits that are a subtype of the specified class.
     * 
     * @return An unmodifiable list containing all traits of the specified class.
     */
    @SuppressWarnings("unchecked")
    public <T extends MachineTrait> @UnmodifiableView List<T> getTraits(Class<T> type) {
        List<T> traitList = (List<T>) traitsByClass.get(type);
        if (traitList == null) return List.of();
        return Collections.unmodifiableList(traitList);
    }

    public void machineLoaded() {
        allowTraitAttachment = false;

        // Cache traits so that repeated unmodifiableList calls aren't required.

        allTraits = Collections.unmodifiableList(traits);
    }

    private static class MachineTraitHolderTransformer implements ValueTransformer<MachineTraitHolder> {

        @Override
        public Tag serializeNBT(MachineTraitHolder value, TransformerContext<MachineTraitHolder> context) {
            CompoundTag tag = new CompoundTag();

            value.traitsToSave.forEach((k, v) -> tag.put(k, v.getSyncDataHolder().serializeNBT(context.lookup())));

            return tag;
        }

        @Override
        public @Nullable MachineTraitHolder deserializeNBT(Tag tag, TransformerContext<MachineTraitHolder> context) {
            var traitHolder = Objects.requireNonNull(context.currentValue());
            var compoundTag = (CompoundTag) tag;

            for (var key : compoundTag.getAllKeys()) {
                var trait = traitHolder.getPersistentTrait(key);
                if (trait == null) {
                    GTCEu.LOGGER.warn("Attempted to deserialise syncable trait '{}', but no syncable trait has that ID",
                            key);
                    continue;
                }

                trait.getSyncDataHolder().deserializeNBT(context.lookup(), compoundTag.getCompound(key));
            }

            return traitHolder;
        }

        @Override
        public void writeToPacket(FriendlyByteBuf buf, MachineTraitHolder value,
                                  TransformerContext<MachineTraitHolder> context) {
            buf.writeVarInt(value.traitsToSave.size());
            value.traitsToSave.forEach((name, trait) -> {
                buf.writeUtf(name);
                if (context.isClientFullSyncUpdate()) trait.getSyncDataHolder().resyncAllFields();
                trait.getSyncDataHolder().writeClientPacket(context.lookup(), buf);
            });
        }

        @Override
        public @Nullable MachineTraitHolder readFromPacket(FriendlyByteBuf buf,
                                                           TransformerContext<MachineTraitHolder> context) {
            var traitHolder = Objects.requireNonNull(context.currentValue());
            int length = buf.readVarInt();
            for (int i = 0; i < length; i++) {
                String name = buf.readUtf();

                var trait = traitHolder.getPersistentTrait(name);
                if (trait == null) {
                    throw new IllegalStateException(
                            "Reading packet data for syncable trait '%s', but no client-side syncable trait has that ID"
                                    .formatted(name));
                } else {
                    trait.getSyncDataHolder().readClientPacket(context.lookup(), buf);
                }
            }

            return traitHolder;
        }
    }

    static {
        ValueTransformers.registerTransformer(MachineTraitHolder.class, new MachineTraitHolderTransformer());
    }
}

package com.gregtechceu.gtceu.api.machine.trait.notifiable;

import com.gregtechceu.gtceu.api.GTValues;
import com.gregtechceu.gtceu.api.capability.GTCapabilityHelper;
import com.gregtechceu.gtceu.api.capability.IElectricItem;
import com.gregtechceu.gtceu.api.capability.IEnergyContainer;
import com.gregtechceu.gtceu.api.capability.compat.FeCompat;
import com.gregtechceu.gtceu.api.capability.recipe.EURecipeCapability;
import com.gregtechceu.gtceu.api.capability.recipe.IO;
import com.gregtechceu.gtceu.api.capability.recipe.RecipeCapability;
import com.gregtechceu.gtceu.api.machine.TickableSubscription;
import com.gregtechceu.gtceu.api.misc.EnergyContainerList;
import com.gregtechceu.gtceu.api.recipe.GTRecipe;
import com.gregtechceu.gtceu.api.recipe.ingredient.EnergyStack;
import com.gregtechceu.gtceu.api.sync_system.annotations.SaveField;
import com.gregtechceu.gtceu.common.machine.trait.EnvironmentalExplosionTrait;
import com.gregtechceu.gtceu.config.ConfigHolder;
import com.gregtechceu.gtceu.utils.GTUtil;

import net.minecraft.MethodsReturnNonnullByDefault;
import net.minecraft.core.Direction;
import net.minecraftforge.energy.IEnergyStorage;
import net.minecraftforge.items.IItemHandlerModifiable;

import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.Nullable;

import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;

import javax.annotation.ParametersAreNonnullByDefault;

@ParametersAreNonnullByDefault
@MethodsReturnNonnullByDefault
public class NotifiableEnergyContainer extends NotifiableRecipeHandlerTrait<EnergyStack> implements IEnergyContainer {

    @Getter
    protected IO handlerIO;
    @Getter
    @SaveField
    protected long energyStored;
    @Getter
    private long energyCapacity, inputVoltage, inputAmperage, outputVoltage, outputAmperage;
    @Setter
    private @Nullable Predicate<Direction> sideInputCondition, sideOutputCondition;

    protected long amps, lastTimeStamp;
    @Nullable
    protected TickableSubscription outputSubs;
    @Nullable
    protected TickableSubscription updateSubs;

    protected long lastEnergyInputPerSec = 0;
    protected long lastEnergyOutputPerSec = 0;
    protected long energyInputPerSec = 0;
    protected long energyOutputPerSec = 0;

    public NotifiableEnergyContainer(long maxCapacity, long maxInputVoltage, long maxInputAmperage,
                                     long maxOutputVoltage, long maxOutputAmperage) {
        super();
        this.lastTimeStamp = Long.MIN_VALUE;
        this.energyCapacity = maxCapacity;
        this.inputVoltage = maxInputVoltage;
        this.inputAmperage = maxInputAmperage;
        this.outputVoltage = maxOutputVoltage;
        this.outputAmperage = maxOutputAmperage;
        var isIn = (inputVoltage != 0 && inputAmperage != 0);
        var isOut = (outputVoltage != 0 && outputAmperage != 0);
        this.handlerIO = (isIn && isOut) ? IO.BOTH : isIn ? IO.IN : isOut ? IO.OUT : IO.NONE;
    }

    public static NotifiableEnergyContainer emitterContainer(long maxCapacity,
                                                             long maxOutputVoltage, long maxOutputAmperage) {
        return new NotifiableEnergyContainer(maxCapacity, 0L, 0L, maxOutputVoltage, maxOutputAmperage);
    }

    public static NotifiableEnergyContainer receiverContainer(long maxCapacity,
                                                              long maxInputVoltage, long maxInputAmperage) {
        return new NotifiableEnergyContainer(maxCapacity, maxInputVoltage, maxInputAmperage, 0L, 0L);
    }

    public void resetBasicInfo(long maxCapacity, long maxInputVoltage, long maxInputAmperage, long maxOutputVoltage,
                               long maxOutputAmperage) {
        this.energyCapacity = maxCapacity;
        this.inputVoltage = maxInputVoltage;
        this.inputAmperage = maxInputAmperage;
        this.outputVoltage = maxOutputVoltage;
        this.outputAmperage = maxOutputAmperage;
        var isIN = (inputVoltage != 0 && inputAmperage != 0);
        var isOUT = (outputVoltage != 0 && outputAmperage != 0);
        this.handlerIO = (isIN && isOUT) ? IO.BOTH : isIN ? IO.IN : isOUT ? IO.OUT : IO.NONE;
        checkOutputSubscription();
    }

    @Override
    public void onMachineLoad() {
        super.onMachineLoad();
        checkOutputSubscription();
        updateSubs = getMachine().subscribeServerTick(updateSubs, this::updateTick);
    }

    @Override
    public void onMachineUnload() {
        super.onMachineUnload();
        if (updateSubs != null) {
            updateSubs.unsubscribe();
            updateSubs = null;
        }
    }

    public void checkOutputSubscription() {
        if (getOutputVoltage() > 0 && getOutputAmperage() > 0) {
            if (getEnergyStored() >= getOutputVoltage()) {
                outputSubs = getMachine().subscribeServerTick(outputSubs, this::serverTick);
            } else if (outputSubs != null) {
                outputSubs.unsubscribe();
                outputSubs = null;
            }
        }
    }

    @Override
    public long getInputPerSec() {
        return lastEnergyInputPerSec;
    }

    @Override
    public long getOutputPerSec() {
        return lastEnergyOutputPerSec;
    }

    public void setEnergyStored(long energyStored) {
        if (this.energyStored == energyStored) return;
        if (energyStored > this.energyStored) {
            energyInputPerSec += energyStored - this.energyStored;
        } else {
            energyOutputPerSec += this.energyStored - energyStored;
        }
        this.energyStored = energyStored;
        checkOutputSubscription();
        notifyListeners();
    }

    public void updateTick() {
        if (getMachine().getOffsetTimer() % 20 == 0) {
            lastEnergyOutputPerSec = energyOutputPerSec;
            lastEnergyInputPerSec = energyInputPerSec;
            energyOutputPerSec = 0;
            energyInputPerSec = 0;
        }
    }

    public void serverTick() {
        if (getMachine().getLevel().isClientSide)
            return;
        if (getEnergyStored() >= getOutputVoltage() && getOutputVoltage() > 0 && getOutputAmperage() > 0) {
            long outputVoltage = getOutputVoltage();
            long outputAmperes = Math.min(getEnergyStored() / outputVoltage, getOutputAmperage());
            if (outputAmperes == 0) return;
            long amperesUsed = 0;
            for (Direction side : GTUtil.DIRECTIONS) {
                if (!outputsEnergy(side)) continue;
                var oppositeSide = side.getOpposite();
                var energyContainer = GTCapabilityHelper.getEnergyContainer(getLevel(),
                        getBlockPos().relative(side), oppositeSide);
                if (energyContainer != null && energyContainer.inputsEnergy(oppositeSide)) {
                    amperesUsed += energyContainer.acceptEnergyFromNetwork(oppositeSide, outputVoltage,
                            outputAmperes - amperesUsed);
                    if (amperesUsed >= outputAmperes) break;
                }
            }
            if (amperesUsed > 0) {
                setEnergyStored(getEnergyStored() - amperesUsed * outputVoltage);
            }
        }
    }

    public boolean dischargeOrRechargeEnergyContainers(IItemHandlerModifiable itemHandler, int slotIndex,
                                                       boolean simulate) {
        var stackInSlot = itemHandler.getStackInSlot(slotIndex).copy();
        if (stackInSlot.isEmpty()) { // no stack to charge/discharge
            return false;
        }

        var electricItem = GTCapabilityHelper.getElectricItem(stackInSlot);
        if (electricItem != null) {
            if (handleElectricItem(electricItem, simulate)) {
                if (!simulate) {
                    itemHandler.setStackInSlot(slotIndex, stackInSlot);
                }
                return true;
            }
        } else if (ConfigHolder.INSTANCE.compat.energy.nativeEUToFE) {
            IEnergyStorage energyStorage = GTCapabilityHelper.getForgeEnergyItem(stackInSlot);
            if (energyStorage != null && handleForgeEnergyItem(energyStorage, simulate)) {
                if (!simulate) {
                    itemHandler.setStackInSlot(slotIndex, stackInSlot);
                }
                return true;
            }
        }
        return false;
    }

    private boolean handleElectricItem(IElectricItem electricItem, boolean simulate) {
        int machineTier = GTUtil.getTierByVoltage(Math.max(getInputVoltage(), getOutputVoltage()));
        int chargeTier = Math.min(machineTier, electricItem.getTier());
        double chargePercent = (double) getEnergyStored() / (getEnergyCapacity() * 1.0);

        // Check if the item is a battery (or similar), and if we can receive some amount of energy
        if (electricItem.canProvideChargeExternally() && getEnergyCanBeInserted() > 0) {

            // Drain from the battery if we are below 1/3rd energy capacity, and if the tier matches
            if (chargePercent <= 0.33 && chargeTier == machineTier) {
                long dischargedBy = electricItem.discharge(getEnergyCanBeInserted(), machineTier,
                        false, true, simulate);
                if (!simulate) {
                    addEnergy(dischargedBy);
                }
                return dischargedBy > 0L;
            }
        }

        // Else, check if we have above 2/3rds charge
        if (chargePercent > 0.66) {
            long chargedBy = electricItem.charge(getEnergyStored(), chargeTier, false, false);
            if (!simulate) {
                removeEnergy(chargedBy);
            }
            return chargedBy > 0;
        }
        return false;
    }

    private boolean handleForgeEnergyItem(IEnergyStorage energyStorage, boolean simulate) {
        int machineTier = GTUtil.getTierByVoltage(Math.max(getInputVoltage(), getOutputVoltage()));
        double chargePercent = getEnergyStored() / (getEnergyCapacity() * 1.0);

        if (chargePercent > 0.66) { // 2/3rds full
            long chargedBy = FeCompat.insertEu(energyStorage, GTValues.V[machineTier], simulate);
            if (!simulate) {
                removeEnergy(chargedBy);
            }
            return chargedBy > 0;
        }
        return false;
    }

    @Override
    public long acceptEnergyFromNetwork(Direction side, long voltage, long amperage) {
        var latestTimeStamp = getMachine().getOffsetTimer();
        if (lastTimeStamp < latestTimeStamp) {
            amps = 0;
            lastTimeStamp = latestTimeStamp;
        }
        if (amps >= getInputAmperage()) return 0;
        long canAccept = getEnergyCapacity() - getEnergyStored();
        if (voltage > 0L && inputsEnergy(side)) {
            if (voltage > getInputVoltage()) {
                var explodable = getMachine().getTrait(EnvironmentalExplosionTrait.class);
                if (explodable != null)
                    GTUtil.doExplosion(getLevel(), getBlockPos(), GTUtil.getExplosionPower(voltage));
                return Math.min(amperage, getInputAmperage() - amps);
            }
            if (canAccept >= voltage) {
                long amperesAccepted = Math.min(canAccept / voltage, Math.min(amperage, getInputAmperage() - amps));
                if (amperesAccepted > 0) {
                    setEnergyStored(getEnergyStored() + voltage * amperesAccepted);
                    amps += amperesAccepted;
                    return amperesAccepted;
                }
            }
        }
        return 0;
    }

    @Override
    public boolean inputsEnergy(Direction side) {
        return !outputsEnergy(side) && getInputVoltage() > 0 &&
                (sideInputCondition == null || sideInputCondition.test(side));
    }

    @Override
    public boolean outputsEnergy(Direction side) {
        return getOutputVoltage() > 0 && (sideOutputCondition == null || sideOutputCondition.test(side));
    }

    @Override
    public long changeEnergy(long energyToAdd) {
        long oldEnergyStored = getEnergyStored();
        long newEnergyStored = (energyCapacity - oldEnergyStored < energyToAdd) ? energyCapacity :
                (oldEnergyStored + energyToAdd);
        if (newEnergyStored < 0)
            newEnergyStored = 0;
        setEnergyStored(newEnergyStored);
        return newEnergyStored - oldEnergyStored;
    }

    @Override
    public List<EnergyStack> handleRecipeInner(IO io, GTRecipe recipe, List<EnergyStack> left,
                                               boolean simulate) {
        for (var it = left.listIterator(); it.hasNext();) {
            EnergyStack stack = it.next();
            if (stack.isEmpty()) {
                it.remove();
                continue;
            }

            long totalEU = stack.getTotalEU();
            long canTransfer = Math.min(totalEU, (io == IO.IN ? this.getEnergyStored() :
                    this.getEnergyCapacity() - this.getEnergyStored()));
            if (!simulate) {
                // invert the EU value if we're doing inputs (inputting *to the recipe* -> removing from handlers)
                this.changeEnergy(io == IO.IN ? -canTransfer : canTransfer);
            }

            totalEU -= canTransfer;
            if (totalEU <= 0) {
                it.remove();
            } else {
                it.set(new EnergyStack(totalEU));
            }

        }

        return left;
    }

    @Override
    public List<Object> getContents() {
        long amperage = Math.max(getInputAmperage(), getOutputAmperage());
        return Collections.singletonList(EnergyContainerList.calculateVoltageAmperage(getEnergyStored(), amperage));
    }

    @Override
    public double getTotalContentAmount() {
        return energyStored;
    }

    @Override
    public RecipeCapability<EnergyStack> getCapability() {
        return EURecipeCapability.CAP;
    }
}

package com.gregtechceu.gtceu.api.sync_system;

import com.gregtechceu.gtceu.GTCEu;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformer;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformers;
import com.gregtechceu.gtceu.api.sync_system.managed.ISyncManaged;

import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;

import io.netty.buffer.Unpooled;
import it.unimi.dsi.fastutil.objects.ObjectOpenHashSet;
import it.unimi.dsi.fastutil.objects.ObjectSet;
import lombok.Setter;
import org.jetbrains.annotations.Nullable;

import java.lang.invoke.MethodHandle;
import java.lang.invoke.WrongMethodTypeException;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Class that holds all sync info for an {@link ISyncManaged} object.
 */
public class SyncDataHolder {

    private final ClassSyncData syncData;
    private final ISyncManaged holder;

    private final ObjectSet<String> dirtySyncFields = new ObjectOpenHashSet<>();
    @Setter
    private boolean hasDirtyChildSyncObject = false;
    private boolean resyncAll = false;

    public SyncDataHolder(ISyncManaged o) {
        holder = o;
        syncData = ClassSyncData.getClassData(o.getClass());
    }

    /**
     * Instructs the sync system that this field has been updated and must be synced with clients.
     * 
     * @param fieldName The field that has changed.
     */
    public void markClientSyncFieldDirty(String fieldName) {
        dirtySyncFields.add(fieldName);
        holder.markAsChanged();
    }

    public void resyncAllFields() {
        resyncAll = true;
        holder.markAsChanged();
    }

    public boolean needsSync() {
        return !dirtySyncFields.isEmpty() || resyncAll || hasDirtyChildSyncObject;
    }

    @SuppressWarnings("unchecked")
    public CompoundTag serializeNBT(HolderLookup.Provider lookup) {
        CompoundTag tag = new CompoundTag();
        for (var field : syncData.getServerSaveFields().values()) {
            Object currentValue = field.handle.get(holder);
            if (currentValue == null || !confirmTransformerPresent(field, holder)) continue;

            try {
                Tag nbtValue = ((ValueTransformer<Object>) Objects.requireNonNull(field.transformer))
                        .serializeNBT(currentValue,
                                new ValueTransformer.TransformerContext<>(holder, field.type, currentValue,
                                        field.fieldName,
                                        false, false, lookup));
                tag.put(field.nbtSaveKey, nbtValue);

            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to serialize field {}", field.fieldName, e);
            }
        }
        return tag;
    }

    @SuppressWarnings("unchecked")
    public void deserializeNBT(HolderLookup.Provider lookup, CompoundTag tag) {
        for (var field : syncData.getServerSaveFields().values()) {
            Tag newValue = tag.get(field.nbtSaveKey);
            if (newValue == null || newValue instanceof CompoundTag compound &&
                    (compound.isEmpty() || (compound.size() == 1 && compound.getBoolean("null"))))
                continue;

            if (!confirmTransformerPresent(field, holder)) continue;

            try {
                ValueTransformer<Object> transformer = (ValueTransformer<Object>) field.transformer;
                var current = field.handle.get(holder);

                Object result = Objects.requireNonNull(transformer).deserializeNBT(newValue,
                        new ValueTransformer.TransformerContext<>(
                                holder, field.type, current, field.fieldName, false, false, lookup));

                if (result != current) trySetField(field, holder, result);

            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to deserialize field {}", field.fieldName, e);
            }
        }
    }

    @SuppressWarnings("unchecked")
    public void writeClientPacket(HolderLookup.Provider lookup, FriendlyByteBuf buf) {
        Set<FieldSyncData> fieldsToSerialize = syncData.getClientSyncFields().values().stream()
                .filter(this::shouldSyncFieldToClient).collect(Collectors.toSet());

        var fieldData = new FriendlyByteBuf(Unpooled.buffer());
        boolean hadErrorWritingData = false;

        for (var field : fieldsToSerialize) {
            Object currentValue = field.handle.get(holder);

            fieldData.writeUtf(field.fieldName);
            fieldData.writeBoolean(currentValue == null);
            if (currentValue == null) continue;

            if (!confirmTransformerPresent(field, holder)) continue;

            try {
                ((ValueTransformer<Object>) Objects.requireNonNull(field.transformer))
                        .writeToPacket(fieldData, currentValue,
                                new ValueTransformer.TransformerContext<>(holder, field.type, currentValue,
                                        field.fieldName,
                                        true, resyncAll, lookup));
            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to write client packet on field {}", field.fieldName, e);
                hadErrorWritingData = true;
                break;
            }
        }

        resyncAll = false;
        dirtySyncFields.clear();
        hasDirtyChildSyncObject = false;

        if (hadErrorWritingData) {
            buf.writeVarInt(0);
            return;
        }

        buf.writeVarInt(fieldsToSerialize.size());
        buf.writeBytes(fieldData);
    }

    @SuppressWarnings("unchecked")
    public void readClientPacket(HolderLookup.Provider lookup, FriendlyByteBuf buf) {
        int fieldsToRead = buf.readVarInt();

        for (int fieldIndex = 0; fieldIndex < fieldsToRead; fieldIndex++) {
            String fieldName = buf.readUtf();
            FieldSyncData field = syncData.getClientSyncFields().get(fieldName);

            if (field == null) {
                GTCEu.LOGGER.error("Sync: Failed to read client packet: Unknown field {}", fieldName);
                return;
            }

            Object currentValue = field.handle.get(holder);

            boolean isNull = buf.readBoolean();
            if (isNull) {
                trySetField(field, holder, null);
                executeClientsideUpdateCallbacks(field);
                continue;
            }

            if (!confirmTransformerPresent(field, holder)) continue;

            try {
                Object result = ((ValueTransformer<Object>) Objects.requireNonNull(field.transformer))
                        .readFromPacket(buf,
                                new ValueTransformer.TransformerContext<>(holder, field.type, currentValue,
                                        field.fieldName,
                                        true, resyncAll, lookup));

                if (result != currentValue) {
                    trySetField(field, holder, result);
                }
                executeClientsideUpdateCallbacks(field);
            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to read client packet on field {}", field.fieldName, e);
                return;
            }

        }
    }

    private boolean shouldSyncFieldToClient(FieldSyncData field) {
        return (resyncAll || dirtySyncFields.contains(field.fieldName) ||
                field.handle.get(holder) instanceof ISyncManaged syncManaged &&
                        syncManaged.getSyncDataHolder().needsSync());
    }

    private void executeClientsideUpdateCallbacks(FieldSyncData field) {
        try {
            for (MethodHandle changeListenerHandle : field.changeListenerHandles) {
                changeListenerHandle.invoke(holder);
            }
        } catch (Throwable e) {
            if (e instanceof WrongMethodTypeException) {
                throw new IllegalArgumentException(
                        "Invalid method signature for change listener for field %s %s"
                                .formatted(field.fieldName, holder.getClass().getName()));
            }
            GTCEu.LOGGER.error("Sync: Error while invoking change listener for field {}", field.fieldName, e);
        }

        if (field.triggerClientRerender) holder.scheduleRenderUpdate();
    }

    @SuppressWarnings("BooleanMethodIsAlwaysInverted")
    private static boolean confirmTransformerPresent(FieldSyncData field, Object holder) {
        if (field.transformer == null) {
            field.setTransformer(ValueTransformers.get(field.type.getRawType()));
            if (field.transformer == null) {
                GTCEu.LOGGER.error(
                        "Sync: Failed to serialize/deserialize field {} in class {}: Missing value transformer for {}",
                        field.fieldName, holder.getClass().getName(), field.type);
                return false;
            }
        }
        return true;
    }

    private static void trySetField(FieldSyncData field, Object holder, @Nullable Object value) {
        try {
            field.handle.set(holder, value);
        } catch (Exception e) {
            if (e instanceof UnsupportedOperationException) {
                GTCEu.LOGGER.error(
                        "Sync: failed to perform VarHandle set: unsupported op on {} (you are probably trying to sync a final field)",
                        field.fieldName);
                return;
            }
            GTCEu.LOGGER.error("Sync: Failed to perform VarHandle set on {} : {}", field.fieldName, e);
        }
    }

    public static class SyncManagedTransformer implements ValueTransformer<ISyncManaged> {

        @Override
        public Tag serializeNBT(ISyncManaged value, TransformerContext<ISyncManaged> context) {
            return value.getSyncDataHolder().serializeNBT(context.lookup());
        }

        @Override
        public @Nullable ISyncManaged deserializeNBT(Tag tag, TransformerContext<ISyncManaged> context) {
            ISyncManaged syncManaged = context.currentValue();

            if (syncManaged == null) {
                GTCEu.LOGGER.error("Sync: ISyncManaged field was null, cannot instantiate {}",
                        context.fieldName());
                return null;
            }

            syncManaged.getSyncDataHolder().deserializeNBT(context.lookup(), (CompoundTag) tag);
            return syncManaged;
        }

        @Override
        public void writeToPacket(FriendlyByteBuf buf, ISyncManaged value, TransformerContext<ISyncManaged> context) {
            if (context.isClientFullSyncUpdate()) value.getSyncDataHolder().resyncAllFields();
            value.getSyncDataHolder().writeClientPacket(context.lookup(), buf);
        }

        @Override
        public @Nullable ISyncManaged readFromPacket(FriendlyByteBuf buf, TransformerContext<ISyncManaged> context) {
            ISyncManaged syncManaged = context.currentValue();
            var clazz = context.type().getClassValue();

            if (syncManaged == null && clazz != null && ISyncManaged.class.isAssignableFrom(clazz)) {
                var ctor = ClassSyncData.getClassData(clazz).getClientsideConstructor();
                if (ctor != null) syncManaged = (ISyncManaged) ctor.get();
            }

            if (syncManaged == null) {
                GTCEu.LOGGER.error("Sync: ISyncManaged field was null on client, cannot instantiate {}",
                        context.fieldName());
                return null;
            }

            syncManaged.getSyncDataHolder().readClientPacket(context.lookup(), buf);
            return syncManaged;
        }
    }
}

package com.gregtechceu.gtceu.api.sync_system.data_transformers;

import com.gregtechceu.gtceu.GTCEu;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraftforge.common.util.INBTSerializable;

import javax.annotation.Nullable;

public class NBTSerializableTransformer implements ValueTransformer<INBTSerializable<Tag>> {

    @Override
    public Tag serializeNBT(INBTSerializable<Tag> value,
                            ValueTransformer.TransformerContext<INBTSerializable<Tag>> context) {
        return value.serializeNBT();
    }

    @Override
    public @Nullable INBTSerializable<Tag> deserializeNBT(Tag tag,
                                                          ValueTransformer.TransformerContext<INBTSerializable<Tag>> context) {
        var currentVal = context.currentValue();
        if (currentVal == null) {
            GTCEu.LOGGER.warn(
                    "Sync: Deserialization of INBTSerializable objects requires an existing object, they cannot be instantiated purely from saved data.");
            return null;
        }
        currentVal.deserializeNBT(tag);
        return currentVal;
    }

    private static final String WRAPPED_TAG_KEY = "$$field$$";

    @Override
    public void writeToPacket(FriendlyByteBuf buf, INBTSerializable<Tag> value,
                              TransformerContext<INBTSerializable<Tag>> context) {
        Tag data = value.serializeNBT();
        if (data instanceof CompoundTag compoundTag) {
            buf.writeNbt(compoundTag);
        } else {
            CompoundTag wrapper = new CompoundTag();
            wrapper.put(WRAPPED_TAG_KEY, data);
            buf.writeNbt(wrapper);
        }
    }

    @Override
    public @Nullable INBTSerializable<Tag> readFromPacket(FriendlyByteBuf buf,
                                                          TransformerContext<INBTSerializable<Tag>> context) {
        var currentVal = context.currentValue();
        Tag read = buf.readNbt();
        if (read instanceof CompoundTag compound && compound.size() == 1 && compound.contains(WRAPPED_TAG_KEY)) {
            read = compound.get(WRAPPED_TAG_KEY);
        }
        if (currentVal == null) {
            GTCEu.LOGGER.warn(
                    "Sync: Deserialization of INBTSerializable objects requires an existing object, they cannot be instantiated purely from a client packet.");
            return null;
        }
        if (read != null) currentVal.deserializeNBT(read);
        return currentVal;
    }
}

