    public static String formattedBucketValue(int millibuckets, BucketMode bucketMode) {
        if (bucketMode == BucketMode.MILLI_BUCKET) return String.valueOf(millibuckets);
        StringBuilder buckets = new StringBuilder(String.format("%04d", millibuckets));
        buckets.insert(buckets.length() - 3, '.');
        return buckets.toString();
    }

    public static int bucketsFromFormattedValue(String uiInput, BucketMode bucketMode) {
        if (bucketMode == BucketMode.MILLI_BUCKET) return Integer.parseInt(uiInput);
        if (!uiInput.contains(".")) return Integer.parseInt(uiInput) * 1000;
        String[] splitInput = uiInput.split("\\.");
        if (splitInput.length > 1 && splitInput[1].length() > 3) splitInput[1] = splitInput[1].substring(0, 3);
        return (Integer.parseInt(splitInput[0]) * 1000) + Integer.parseInt(splitInput[1]);
    }

    public static SlotGroupWidget verticalPlayerInventory(SlotGroupWidget.SlotConsumer slotConsumer) {
        SlotGroupWidget slotGroupWidget = new SlotGroupWidget();
        slotGroupWidget.coverChildren();
        slotGroupWidget.name("player_inventory");
        String key = "player";

        for (int i = 0; i < 9; ++i) {
            slotGroupWidget
                    .child(slotConsumer.apply(i, new ItemSlot()).syncHandler(key, i).pos(0, i * 18).name("slot_" + i));
        }

        for (int i = 0; i < 27; ++i) {
            slotGroupWidget.child(slotConsumer.apply(i + 9, new ItemSlot()).syncHandler(key, i + 9)
                    .pos(22 + i / 9 * 18, i % 9 * 18).name("slot_" + (i + 9)));
        }

        return slotGroupWidget;
    }

    public static class EnumRowBuilder<T extends Enum<T>> {

        private @Nullable EnumSyncValue<T> syncValue;
        private final Class<T> enumValue;
        private @Nullable Component lang;
        private @Nullable List<Component> langTooltip;
        private @Nullable Function<T, Supplier<Component>> buttonTooltipSupplier;
        private IDrawable @Nullable [] background;
        private @Nullable IDrawable selectedBackground;
        private IDrawable @Nullable [] overlay;

        public EnumRowBuilder(Class<T> enumValue) {
            this.enumValue = enumValue;
        }

        public EnumRowBuilder<T> value(EnumSyncValue<T> syncValue) {
            this.syncValue = syncValue;
            return this;
        }

        public EnumRowBuilder<T> lang(Component lang) {
            this.lang = lang;
            return this;
        }

        public EnumRowBuilder<T> langTooltip(Component tooltip) {
            this.langTooltip = Collections.singletonList(tooltip);
            return this;
        }

        public EnumRowBuilder<T> multiLangTooltip(Component... tooltips) {
            this.langTooltip = List.of(tooltips);
            return this;
        }

        public EnumRowBuilder<T> multiLangTooltip(List<Component> tooltips) {
            this.langTooltip = tooltips;
            return this;
        }

        public EnumRowBuilder<T> background(IDrawable... background) {
            this.background = background;
            return this;
        }

        public EnumRowBuilder<T> selectedBackground(IDrawable selectedBackground) {
            this.selectedBackground = selectedBackground;
            return this;
        }

        public EnumRowBuilder<T> overlay(IDrawable... overlay) {
            this.overlay = overlay;
            return this;
        }

        public EnumRowBuilder<T> overlay(int size, IDrawable... overlay) {
            this.overlay = new IDrawable[overlay.length];
            for (int i = 0; i < overlay.length; i++) {
                this.overlay[i] = overlay[i].asIcon().size(size);
            }
            return this;
        }

        public EnumRowBuilder<T> buttonTooltipSupplier(Function<T, Supplier<Component>> buttonTooltipSupplier) {
            this.buttonTooltipSupplier = buttonTooltipSupplier;
            return this;
        }

        private BoolValue.Dynamic boolValueOf(EnumSyncValue<T> syncValue, T value) {
            return new BoolValue.Dynamic(() -> syncValue.getValue() == value, $ -> syncValue.setValue(value));
        }

        public Flow build() {
            var row = Flow.row().coverChildrenHeight().widthRel(1f);
            if (syncValue != null) {
                for (var enumVal : enumValue.getEnumConstants()) {
                    var button = new ToggleButton().size(18).marginRight(2)
                            .value(boolValueOf(Objects.requireNonNull(syncValue), enumVal));

                    if (this.background != null && this.background.length > 0)
                        button.background(this.background);
                    else
                        button.background(GuiTextures.MC_BUTTON);

                    if (this.selectedBackground != null)
                        button.background(true, this.selectedBackground);
                    else
                        button.background(true, GuiTextures.MC_BUTTON_DISABLED);

                    if (this.overlay != null)
                        button.overlay(this.overlay[enumVal.ordinal()]);

                    if (this.buttonTooltipSupplier != null) {
                        button.addTooltipLine(Text.comp(buttonTooltipSupplier.apply(enumVal).get()));
                    } else if (enumVal instanceof StringRepresentable serializable) {
                        button.addTooltipLine(Text.lang(serializable.getSerializedName()));
                    }
                    row.child(button);
                }
            }

            if (this.lang != null) {
                TextWidget<?> text = Text.comp(lang)
                        .asWidget()
                        .verticalCenter()
                        .rightRel(0.f)
                        .height(18);
                if (this.langTooltip != null) {
                    text.tooltip(r -> langTooltip.forEach(r::addLine));
                }
                row.child(text);
            }
            return row;
        }
    }
}

package com.gregtechceu.gtceu.utils.data;

import com.gregtechceu.gtceu.api.machine.MetaMachine;
import com.gregtechceu.gtceu.api.machine.trait.MachineTrait;
import com.gregtechceu.gtceu.common.machine.trait.AutoOutputTrait;
import com.gregtechceu.gtceu.common.machine.trait.BatterySlotTrait;
import com.gregtechceu.gtceu.common.machine.trait.ProgrammableCircuitSlotTrait;

import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;

import lombok.AccessLevel;
import lombok.NoArgsConstructor;

import java.util.Objects;

@NoArgsConstructor(access = AccessLevel.PRIVATE)
public final class TagCompatibilityFixer {

    public static void putTraitTag(MetaMachine machine, CompoundTag machineTag,
                                   Class<? extends MachineTrait> type, String defaultName,
                                   CompoundTag data) {
        var traits = machine.getTraits(type);

        if (traits.size() != 1 || traits.get(0).getTraitName() == null) {
            machineTag.put(defaultName, data);
            return;
        }

        var persistent = traits.get(0).getTraitName();
        machineTag.getCompound("traitHolder").put(Objects.requireNonNull(persistent), data);
    }

    public static void fixTraitTags(MetaMachine machine, CompoundTag tag) {
        if (!tag.contains("traitHolder")) {
            tag.put("traitHolder", new CompoundTag());

            fixBatterySlotTag(machine, tag);
            fixProgrammedCircutTag(machine, tag);
            fixMachineAutoOutputTag(machine, tag);
        }
    }

    public static void fixBatterySlotTag(MetaMachine machine, CompoundTag tag) {
        if (tag.contains("chargerInventory")) {
            var newTag = new CompoundTag();
            newTag.put("storage", Objects.requireNonNull(tag.get("chargerInventory")));

            putTraitTag(machine, tag, BatterySlotTrait.class, "batterySlot", newTag);
        }
    }

    public static void fixProgrammedCircutTag(MetaMachine machine, CompoundTag tag) {
        if (tag.contains("circuitInventory")) {
            var oldData = tag.getCompound("circuitInventory");

            putTraitTag(machine, tag, ProgrammableCircuitSlotTrait.class, "circuitSlot", oldData);
        }
    }

    public static void fixMachineAutoOutputTag(MetaMachine machine, CompoundTag machineTag) {
        var outputTag = new CompoundTag();
        Tag itemOutputDirection = machineTag.get("outputFacingItems");
        Tag fluidOutputDirection = machineTag.get("outputFacingFluids");
        Tag autoOutputItems = machineTag.get("autoOutputItems");
        Tag autoOutputFluids = machineTag.get("autoOutputFluids");
        Tag allowInputItems = machineTag.get("allowInputFromOutputSideItems");
        Tag allowInputFluids = machineTag.get("allowInputFromOutputSideFluids");
        if (itemOutputDirection != null) outputTag.put("itemOutputDirection", itemOutputDirection);
        if (fluidOutputDirection != null) outputTag.put("fluidOutputDirection", fluidOutputDirection);
        if (autoOutputItems != null) outputTag.put("autoOutputItems", autoOutputItems);
        if (autoOutputFluids != null) outputTag.put("autoOutputFluids", autoOutputFluids);
        if (allowInputItems != null) outputTag.put("allowItemInputFromOutputSide", allowInputItems);
        if (allowInputFluids != null) outputTag.put("allowFluidInputFromOutputSide", allowInputFluids);

        putTraitTag(machine, machineTag, AutoOutputTrait.class, "autoOutput", outputTag);
    }

    public static Direction fixUpwardsFacing(Direction frontfacing, Direction upwardsFacing) {
        Direction newUpwards;
        switch (frontfacing) {
            case NORTH: {
                if (upwardsFacing == Direction.NORTH) {
                    newUpwards = Direction.UP;
                } else if (upwardsFacing == Direction.EAST) {
                    newUpwards = Direction.WEST;
                } else if (upwardsFacing == Direction.SOUTH) {
                    newUpwards = Direction.DOWN;
                } else if (upwardsFacing == Direction.WEST) {
                    newUpwards = Direction.EAST;
                } else {
                    newUpwards = Direction.UP;
                }
                break;
            }
            case EAST: {
                if (upwardsFacing == Direction.NORTH) {
                    newUpwards = Direction.UP;
                } else if (upwardsFacing == Direction.EAST) {
                    newUpwards = Direction.NORTH;
                } else if (upwardsFacing == Direction.SOUTH) {
                    newUpwards = Direction.DOWN;
                } else if (upwardsFacing == Direction.WEST) {
                    newUpwards = Direction.SOUTH;
                } else {
                    newUpwards = Direction.UP;
                }
                break;
            }
            case SOUTH: {
                if (upwardsFacing == Direction.NORTH) {
                    newUpwards = Direction.UP;
                } else if (upwardsFacing == Direction.EAST) {
                    newUpwards = Direction.EAST;
                } else if (upwardsFacing == Direction.SOUTH) {
                    newUpwards = Direction.DOWN;
                } else if (upwardsFacing == Direction.WEST) {
                    newUpwards = Direction.WEST;
                } else {
                    newUpwards = Direction.UP;
                }
                break;
            }
            case WEST: {
                if (upwardsFacing == Direction.NORTH) {
                    newUpwards = Direction.UP;
                } else if (upwardsFacing == Direction.EAST) {
                    newUpwards = Direction.SOUTH;
                } else if (upwardsFacing == Direction.SOUTH) {
                    newUpwards = Direction.DOWN;
                } else if (upwardsFacing == Direction.WEST) {
                    newUpwards = Direction.NORTH;
                } else {
                    newUpwards = Direction.UP;
                }
                break;
            }
            case DOWN:
            case UP:
            default: {
                newUpwards = upwardsFacing;
                // needed if previous machine did not have an upwards facing
                if (upwardsFacing == null) {
                    newUpwards = Direction.NORTH;
                }
            }
        }
        return newUpwards;
    }

    public static Tag stripLDLibPayloadWrapper(Tag t) {
        if (!(t instanceof CompoundTag tag)) return t;
        if (tag.contains("p") && tag.contains("t")) {
            return tag.getCompound("p");
        }
        if (tag.contains("t", Tag.TAG_COMPOUND)) {
            return tag.getCompound("t").getCompound("p");
        }
        return tag;
    }
}
